window.S17Page={"sceneId":"c3","caseId":"s17x-c3-cement-loss-risk","name":"固井漏失风险预测","title":"固井漏失风险预测","summary":"调整压力裕度和判定阈值，比较多变量风险筛查与单压力裕度规则的漏报、误报。","directory":"expansion-cases","caseVersion":"1.1.0","portalHref":"../../../../portal/index.html","referenceHref":"../../../../portal/reference/fluorescence.html"};
